/**
 * Wake Lock manager — keeps the screen awake during transcription.
 *
 * Combines three mechanisms for cross-browser/cross-device reliability:
 *   1. Screen Wake Lock API (Chrome, Edge, Firefox 126+, iOS Safari 16.4+).
 *   2. Silent looping <video> element (NoSleep.js technique — required on iOS
 *      Safari where Wake Lock alone does not survive the screen lock button).
 *   3. Off-screen canvas 1×1 animation + 30s reacquire poll (legacy fallback).
 *
 * Embedded data URLs courtesy of richtr/NoSleep.js (MIT).
 */

const NO_SLEEP_VIDEO_WEBM =
  'data:video/webm;base64,';

const NO_SLEEP_VIDEO_MP4 =
  'data:video/mp4;base64,';

/**
 * @param {() => boolean} getIsRecording - reactive reader for the recording flag
 * @returns {{ activate: () => Promise<void>, release: () => void, isActive: () => boolean, isSupported: () => boolean, destroy: () => void }}
 */
export function createWakeLockManager(getIsRecording) {
  let sentinel = null;
  let wantWakeLock = false;
  let supported = typeof navigator !== 'undefined' && 'wakeLock' in navigator;

  let noSleepVideo = null;
  let keepAliveCanvas = null;
  let keepAliveInterval = null;
  let visibilityHandler = null;

  async function requestSentinel() {
    if (!supported || sentinel || !wantWakeLock) return;
    try {
      const lock = await navigator.wakeLock.request('screen');
      sentinel = lock;
      lock.addEventListener('release', () => {
        if (sentinel === lock) sentinel = null;
        if (wantWakeLock && getIsRecording()) {
          setTimeout(() => {
            requestSentinel().catch(() => {});
          }, 100);
        }
      });
    } catch (error) {
      if (error && error.name === 'NotSupportedError') {
        supported = false;
        console.warn('Wake Lock non supporté:', error.message);
      } else {
        console.warn('Wake Lock indisponible (transitoire):', error && error.message);
      }
    }
  }

  function startNoSleepVideo() {
    if (noSleepVideo || typeof document === 'undefined') return;
    const video = document.createElement('video');
    video.setAttribute('muted', '');
    video.setAttribute('playsinline', '');
    video.setAttribute('webkit-playsinline', '');
    video.setAttribute('title', 'NoSleep');
    video.muted = true;
    video.playsInline = true;
    video.loop = true;
    video.autoplay = true;
    video.style.position = 'fixed';
    video.style.top = '-9999px';
    video.style.left = '-9999px';
    video.style.width = '1px';
    video.style.height = '1px';
    video.style.opacity = '0';
    video.style.pointerEvents = 'none';

    const webmSource = document.createElement('source');
    webmSource.type = 'video/webm';
    webmSource.src = NO_SLEEP_VIDEO_WEBM;
    const mp4Source = document.createElement('source');
    mp4Source.type = 'video/mp4';
    mp4Source.src = NO_SLEEP_VIDEO_MP4;
    video.appendChild(webmSource);
    video.appendChild(mp4Source);

    document.body.appendChild(video);
    noSleepVideo = video;

    const playPromise = video.play();
    if (playPromise && typeof playPromise.catch === 'function') {
      playPromise.catch((err) => {
        console.warn('NoSleep video play() refusé:', err && err.message);
      });
    }
  }

  function stopNoSleepVideo() {
    if (!noSleepVideo) return;
    try {
      noSleepVideo.pause();
      while (noSleepVideo.firstChild) {
        noSleepVideo.removeChild(noSleepVideo.firstChild);
      }
      noSleepVideo.removeAttribute('src');
      noSleepVideo.load();
    } catch (e) {
      /* ignore */
    }
    if (noSleepVideo.parentNode) {
      noSleepVideo.parentNode.removeChild(noSleepVideo);
    }
    noSleepVideo = null;
  }

  function startCanvasKeepAlive() {
    if (typeof document === 'undefined') return;

    if (!keepAliveCanvas) {
      keepAliveCanvas = document.createElement('canvas');
      keepAliveCanvas.width = 1;
      keepAliveCanvas.height = 1;
      keepAliveCanvas.style.position = 'fixed';
      keepAliveCanvas.style.top = '-9999px';
      keepAliveCanvas.style.opacity = '0';
      keepAliveCanvas.style.pointerEvents = 'none';
      document.body.appendChild(keepAliveCanvas);
    }

    const ctx = keepAliveCanvas.getContext('2d');
    let frame = 0;

    if (keepAliveInterval) clearInterval(keepAliveInterval);
    keepAliveInterval = setInterval(() => {
      if (!wantWakeLock || !getIsRecording()) {
        return;
      }
      ctx.fillStyle = `rgba(${frame % 2}, ${frame % 2}, ${frame % 2}, 0.01)`;
      ctx.fillRect(0, 0, 1, 1);
      frame++;

      if (supported && !sentinel) {
        requestSentinel().catch(() => {});
      }
    }, 30000);

    if (!visibilityHandler) {
      visibilityHandler = () => {
        if (
          document.visibilityState === 'visible' &&
          wantWakeLock &&
          getIsRecording() &&
          supported &&
          !sentinel
        ) {
          requestSentinel().catch(() => {});
        }
      };
      document.addEventListener('visibilitychange', visibilityHandler);
    }

    document.body.classList.add('keep-screen-awake');
  }

  function stopCanvasKeepAlive() {
    if (keepAliveInterval) {
      clearInterval(keepAliveInterval);
      keepAliveInterval = null;
    }
    if (keepAliveCanvas && keepAliveCanvas.parentNode) {
      keepAliveCanvas.parentNode.removeChild(keepAliveCanvas);
      keepAliveCanvas = null;
    }
    if (visibilityHandler) {
      document.removeEventListener('visibilitychange', visibilityHandler);
      visibilityHandler = null;
    }
    if (typeof document !== 'undefined') {
      document.body.classList.remove('keep-screen-awake');
    }
  }

  async function activate() {
    wantWakeLock = true;
    startNoSleepVideo();
    startCanvasKeepAlive();
    await requestSentinel();
  }

  function release() {
    wantWakeLock = false;
    const current = sentinel;
    sentinel = null;
    if (current) {
      try {
        current.release();
      } catch (e) {
        /* ignore */
      }
    }
    stopNoSleepVideo();
    stopCanvasKeepAlive();
  }

  function destroy() {
    release();
  }

  return {
    activate,
    release,
    isActive: () => wantWakeLock || sentinel !== null,
    isSupported: () => supported,
    destroy,
  };
}
